a = input().strip()
b = input().strip()
if a == '0' or b == '0':
    print(0)
else:
    da = [ord(c) - 48 for c in reversed(a)]
    db = [ord(c) - 48 for c in reversed(b)]
    res = [0] * (len(da) + len(db))
    for i, x in enumerate(da):
        if x:
            for j, y in enumerate(db):
                res[i + j] += x * y
    carry = 0
    for k in range(len(res)):
        carry += res[k]
        res[k] = carry % 10
        carry //= 10
    while len(res) > 1 and res[-1] == 0:
        res.pop()
    print(''.join(chr(d + 48) for d in reversed(res)))

